// 100 days back for the last actuals, 120 days forward for the next date. ETFs never report.
const ctx = $input.first().json;
const day = (n) => new Date(new Date(ctx.as_of + 'T00:00:00Z').getTime() + n * 86400000).toISOString().slice(0, 10);
return ctx.tickers.filter(t => !(ctx.benchmarks || []).includes(t)).map(t => ({ json: { ticker: t, from: day(-100), to: day(120), run_id: ctx.run_id } }));

// One full response per ticker. rows -> earnings_calendar, usage -> one ledger row per call.
const ctx = $('When called').first().json;
const reqs = $('One item per ticker').all();
const num = (v) => (v == null || v === '' || !isFinite(Number(v)) ? null : Number(v));
const byKey = new Map(), usage = [], okTickers = [];
$input.all().forEach((it, i) => {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = (pi != null && typeof pi === 'object' ? pi.item : pi) ?? i;
  const ticker = reqs[idx] ? reqs[idx].json.ticker : null;
  const code = Number(it.json.statusCode) || null;
  let body = it.json.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const list = body && Array.isArray(body.earningsCalendar) ? body.earningsCalendar : null;
  const ok = code === 200 && !!list && !!ticker;
  usage.push({ ticker, status: ok ? 'ok' : (code === 429 ? 'quota_skip' : 'error'), http_code: code });
  if (!ok) return;
  okTickers.push(ticker);
  for (const e of list) {
    if (!e || !/^\d{4}-\d{2}-\d{2}$/.test(String(e.date || ''))) continue;
    const est = num(e.epsEstimate), act = num(e.epsActual);
    const surprise = est != null && act != null && est !== 0 ? Math.round(((act - est) / Math.abs(est)) * 100000) / 1000 : null;
    byKey.set(ticker + '|' + e.date, { ticker, report_date: e.date, eps_est: est, eps_actual: act, rev_est: num(e.revenueEstimate), rev_actual: num(e.revenueActual), surprise_pct: surprise, hour: e.hour || null, fiscal_year: num(e.year), fiscal_quarter: num(e.quarter) });
  }
});
const rows = [...byKey.values()];
const failed = usage.filter(u => u.status !== 'ok');
const covered = new Set(rows.filter(r => r.report_date > ctx.as_of).map(r => r.ticker));
const no_date = okTickers.filter(t => !covered.has(t));
return [{ json: { run_id: ctx.run_id, as_of: ctx.as_of, rows, count: rows.length, usage, ok_tickers: okTickers, calls: usage.length, failed: failed.length, failed_tickers: failed.map(u => u.ticker), no_date } }];
